package com.bank.ccr.controller; import com.bank.ccr.model.*; import com.bank.ccr.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/counterparties") @CrossOrigin(origins="*") public class RiskDomainController { private final CollateralRepository collateral; private final NettingSetRepository netting; public RiskDomainController(CollateralRepository c,NettingSetRepository n){collateral=c;netting=n;} @GetMapping("/{id}/collateral") public List<CollateralPosition> collateral(@PathVariable String id){return collateral.findByCounterpartyId(id);} @GetMapping("/{id}/netting-sets") public List<NettingSet> netting(@PathVariable String id){return netting.findByCounterpartyId(id);} }
